194	import hotel.reservations.Reservation;
195	import hotel.reservations.ReservationStore;
196	import java.math.BigDecimal;
197	import java.time.YearMonth;
198	import java.util.ArrayList;
199	import java.util.Comparator;
200	import java.util.List;
201	
202	/**
203	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
204	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
205	 */
206	public final class RevenueReport {
207	
208	    private final ReservationStore store;
209	
210	    public RevenueReport(ReservationStore store) {
211	        this.store = store;
212	    }
213	
214	    public String generate(YearMonth month) {
215	        List<Reservation> withRevenue = new ArrayList<>();
216	        for (Reservation reservation : store.all()) {
217	            boolean keptMoney = reservation.amountKept().signum() > 0;
218	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
219	            if (keptMoney && startsInMonth) {
220	                withRevenue.add(reservation);
221	            }
222	        }
223	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
224	
225	        StringBuilder csv = new StringBuilder();
226	        csv.append("reservation,room,check_in,check_out,status,amount\n");
227	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
228	        for (Reservation reservation : withRevenue) {
229	            csv.append(reservation.id()).append(',')
230	                    .append(reservation.roomNumber()).append(',')
231	                    .append(reservation.checkIn()).append(',')
232	                    .append(reservation.checkOut()).append(',')
233	                    .append(reservation.status()).append(',')
234	                    .append(reservation.amountKept().toPlainString()).append('\n');
235	            revenue = revenue.add(reservation.amountKept());
236	        }
237	        csv.append("total,").append(revenue.toPlainString()).append('\n');
238	        return csv.toString();
239	    }
240	}

